import{_ as a,c as o,o as e,ae as r}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Import Table Data from CSV","description":"Import Table Data from CSV","frontmatter":{"title":"Import Table Data from CSV","description":"Import Table Data from CSV"},"headers":[],"relativePath":"guide/import-export/import-table-data-from-a-csv.md","filePath":"guide/import-export/import-table-data-from-a-csv.md"}'),l={name:"guide/import-export/import-table-data-from-a-csv.md"};function i(n,t,s,p,m,d){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="import-table-data-from-csv" tabindex="-1">Import Table Data from CSV <a class="header-anchor" href="#import-table-data-from-csv" aria-label="Permalink to &quot;Import Table Data from CSV&quot;">​</a></h1><p>If you have an existing table on another website, turn the table data into CSV file (or <strong>JSON</strong>) and import it into Ninja Tables.</p><ul><li>First, go to the Ninja Tables dashboard and click the** Import Table **button (or the &quot;Import&quot; option on the left menubar). Now, press the **Choose File **button. <img src="https://ninjatables.com/wp-content/uploads/2022/09/import-button-01-scaled.webp" alt=""></li><li>Choose the <strong>CSV / JSON</strong> file you want to upload. <img src="https://ninjatables.com/wp-content/uploads/2022/09/02.webp" alt=""></li><li>Click the <strong>Import</strong> button, and then you’re good to go! <strong>Ninja Tables</strong> is going to do the rest for you. Your data will be automatically uploaded. You can also use the &quot;Import-Export&quot; tab at the top of a table to import tables. <img src="https://ninjatables.com/wp-content/uploads/2022/09/03-scaled.webp" alt=""></li></ul><h2 id="table-data-import-for-ms-excel" tabindex="-1">Table Data Import for MS-Excel <a class="header-anchor" href="#table-data-import-for-ms-excel" aria-label="Permalink to &quot;Table Data Import for MS-Excel&quot;">​</a></h2><p>If you have any issue with CSV data imports, such as having blank values in your cell, in case you use MS-Excel, export the CSV as MS-DOS Comma Separated Value (CSV). <img src="https://ninjatables.com/wp-content/uploads/2023/01/import-table-data-from-CSV-2.png" alt="Export As MS-DOS comma-separated (.csv) format"> Ninja table supports only comma-separated CSV and JSON. If your CSV file is not **Comma Separated <strong>&amp; is in another format,</strong> **there is a trick for converting it to make it Comma-Separated-CSV,</p><ul><li>First, go to the **Google Spreadsheet → File → **click on **Import **&amp; then a pop-up will appear. <img src="https://ninjatables.com/wp-content/uploads/2023/01/import-table-data-from-CSV-3.png" alt="Import File"></li><li>Click on the **Upload **button &amp; then upload the CSV file. <img src="https://ninjatables.com/wp-content/uploads/2023/01/import-table-data-from-CSV-4-1024x456.png" alt="Upload button"></li><li>Set the column name as table Column Key, and then **download **it as Comma-Separated-CSV and import it to the existing Ninja Tables.</li></ul>',6)])])}const b=a(l,[["render",i]]);export{u as __pageData,b as default};
